	private static byte[] downgradeSingleSemiAntiSidecar(byte[] versionSeventeen, int targetVersion) {
		/*
		 * These fixtures contain one semi/anti observation and no keyed Frontier-learning observations. The v17 format
		 * prefixes the payload with an 8-byte data stamp after the 24-byte identity, and its tail is exactly revision
		 * (8), exact-key count (4), legacy-prior count (4), and exact-fact count (4). Version 13 also predates the
		 * final two physical semi/anti counters, which immediately precede that tail.
		 */
		int identityBytes = 4 + 24;
		byte[] stampless = new byte[versionSeventeen.length - Long.BYTES];
		System.arraycopy(versionSeventeen, 0, stampless, 0, identityBytes);
		System.arraycopy(versionSeventeen, identityBytes + Long.BYTES, stampless, identityBytes,
				versionSeventeen.length - identityBytes - Long.BYTES);
		int frontierTailBytes = Long.BYTES + 3 * Integer.BYTES;
		ByteBuffer frontierTail = ByteBuffer.wrap(stampless,
				stampless.length - frontierTailBytes, frontierTailBytes).slice();
		assertEquals(0L, frontierTail.getLong());
		assertEquals(0, frontierTail.getInt());
		assertEquals(0, frontierTail.getInt());
		assertEquals(0, frontierTail.getInt());
		int physicalCounterBytes = targetVersion < 14 ? 2 * Long.BYTES : 0;
		byte[] legacy = Arrays.copyOf(stampless,
				stampless.length - frontierTailBytes - physicalCounterBytes);
		ByteBuffer.wrap(legacy).putInt(targetVersion);
		return legacy;
	}

	@Test
	void frontierPlannerDoesNotApplyUnkeyedSemiAntiCounters(@TempDir File dataDir) {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			var values = SimpleValueFactory.getInstance();
			try (var connection = repository.getConnection()) {
				for (int index = 0; index < 10; index++) {
					var person = values.createIRI("urn:test:person:" + index);
					connection.add(person, values.createIRI("urn:test:memberOf"),
							values.createIRI("urn:test:organization"));
					if (index < 6) {
						connection.add(person, values.createIRI("urn:test:blockedBy"),
								values.createIRI("urn:test:blocker"));
					}
				}
			}
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			Filter trained = filter();
			trained.setRuntimeTelemetryEnabled(true);
			trained.setLongMetricActual("actualSemiAntiSourceRowsScanned", 1L);
			for (int index = 0; index < 3; index++) {
				statistics.recordSemiAntiOutcome(trained, lowCostStreamingObservation());
			}

			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(QUERY).explain(Explanation.Level.Optimized);
				Filter planned = findFilter((TupleExpr) explanation.tupleExpr());
				assertNotNull(planned, explanation::toString);
				assertEquals(
						SemiAntiSurfaceKey.from(filter(), "NOT_EXISTS", "streaming-correlated"),
						SemiAntiSurfaceKey.from(planned, "NOT_EXISTS", "streaming-correlated"),
						explanation::toString);
				LmdbOperatorFeedbackStats.SemiAntiEstimate feedback = statistics.estimatorRuntime()
						.semiAntiFeedback(planned, "NOT_EXISTS", "streaming-correlated");
				assertNotNull(feedback);
				assertEquals(3L, feedback.observationCount());
				assertEquals(planned.getStringMetricPlanned("plannedSemiAntiCheapestRawAlgorithm"),
						planned.getStringMetricPlanned("optimizer.semiAntiAlgorithm"),
						"A surface observation without an originating Frontier event must not override candidate costing");
				assertFalse(planned.getDoubleMetricsPlanned().containsKey("plannedSemiAntiFeedbackEvidence"),
						"Unkeyed compatibility counters must remain separate from Frontier event telemetry");
			}
		} finally {
			repository.shutDown();
		}
	}

